      "id": 2,
      "title": "Asset Registry + Glyph-Group + CODECAINE Logo",
      "goal": "Move assets out of inline file paths and behind a registry. assets/registry.json catalogues all reusable assets by id+type+path. Renderer resolves layer.asset references through the registry. New glyph-group renderer mounts the layered CODECAINE.css-layers.svg with all sub-layers visible. Title scene becomes: bg-video → CODECAINE logo (centered, top-third) → CRT overlay.",
      "prerequisites": [1],
      "status": "pending",
      "testing_strategy": "Manual: title scene now shows bg + chrome CODECAINE logo + CRT, all stacked in correct z-order. Programmatically: edit scene.json to change which media asset is referenced by id (e.g. test-fire-3.mp4), reload, confirm switch. Confirm registry resolution fails gracefully on unknown id with a clear console warning.",
      "task_groups": [
        {
          "id": 1,
          "title": "Migrate assets into assets/ tree + author registry.json",
          "objective": "Relocate the bg video and CRT effect from CP1 into the spec-defined assets/ tree, copy the CODECAINE layered SVG into assets/glyphs/, and author assets/registry.json cataloguing all three by id+type+path. No renderer changes yet — this group only moves files and creates the catalogue.",
          "status": "pending",
          "task_seeds": [
            { "title": "Migrate CP1 assets and CODECAINE SVG into apps/scene-engine/assets/", "intent": "Move test-fire-2.mp4 from public/media/ to assets/media/, move src/effects/crt-overlay.css to assets/effects/crt-overlay.css, and copy the CODECAINE.css-layers.svg from the font-creation outputs into assets/glyphs/. Delete the now-empty CP1 locations (public/media/, src/effects/) so there's one canonical home per asset.", "processed": true, "task_id": 1 },
            { "title": "Author assets/registry.json catalogue", "intent": "Create assets/registry.json — a flat object keyed by asset id, each entry having { type, path } where path is the URL-style path Vite serves at runtime. Three entries on day one: bg-video (media → /assets/media/test-fire-2.mp4), crt-overlay (effect → /assets/effects/crt-overlay.css), codecaine-logo (glyph-group → /assets/glyphs/CODECAINE.css-layers.svg).", "processed": true, "task_id": 2 }
          ],
          "tasks": [
            {
              "id": 1,
              "title": "Migrate CP1 assets and CODECAINE SVG into apps/scene-engine/assets/",
              "description": "Reorganize the asset filesystem to match the spec's assets/ tree (spec.md lines 173-207). Move apps/scene-engine/public/media/test-fire-2.mp4 → apps/scene-engine/assets/media/test-fire-2.mp4 (binary copy is fine, but git-track the move so history follows). Move apps/scene-engine/src/effects/crt-overlay.css → apps/scene-engine/assets/effects/crt-overlay.css. Copy apps/font-creation/generation/melee-3/outputs/generated/word/CODECAINE.css-layers.svg → apps/scene-engine/assets/glyphs/CODECAINE.css-layers.svg (this is a copy, not a move — the font-creation outputs remain the source of truth for regeneration; the scene-engine holds a pinned copy that the scene references). After the moves, delete the now-empty apps/scene-engine/public/media/ and apps/scene-engine/src/effects/ directories. Note: in CP1 the bg video served from publicDir at /media/test-fire-2.mp4; under the new layout it's served from /assets/media/test-fire-2.mp4 because Vite serves any file under the project root. The renderer URL update happens in task 4 (registry path is the source of truth from now on); this task only relocates files.",
              "status": "pending",
              "context": {
                "read_before": [
                  { "file": ".spectre/sessions/2026-04-29_frontend-scene-system_aesqad/spec.md", "lines": "173-207", "purpose": "Canonical assets/ tree layout — confirms glyphs/, media/, effects/ as siblings under assets/" },
                  { "file": "apps/scene-engine/vite.config.js", "lines": "1-20", "purpose": "Confirm publicDir setting; once CP1's public/media/ is emptied the publicDir ref is harmless but unused. Do NOT delete publicDir from config in this task — leave it for CP6 cleanup." }
                ],
                "related_files": [
                  "apps/font-creation/generation/melee-3/outputs/generated/word/CODECAINE.css-layers.svg",
                  "apps/scene-engine/public/media/test-fire-2.mp4",
                  "apps/scene-engine/src/effects/crt-overlay.css"
                ]
              },
              "depends_on": [],
              "file_context": {
                "beginning": {
                  "files": [
                    { "path": "apps/scene-engine/public/media/test-fire-2.mp4", "status": "exists", "description": "From CP1 task 1.1.2 — currently served at /media/test-fire-2.mp4" },
                    { "path": "apps/scene-engine/src/effects/crt-overlay.css", "status": "exists", "description": "From CP1 task 1.1.2 — extracted CRT rules" },
                    { "path": "apps/scene-engine/assets/", "status": "new", "description": "Directory does not exist yet" },
                    { "path": "apps/font-creation/generation/melee-3/outputs/generated/word/CODECAINE.css-layers.svg", "status": "exists", "description": "Source SVG, viewBox 0 0 6923 1080, 47 named data-layer groups" }
                  ],
                  "tree": null
                },
                "ending": {
                  "files": [
                    { "path": "apps/scene-engine/assets/media/test-fire-2.mp4", "status": "new", "description": "Relocated from public/media/" },
                    { "path": "apps/scene-engine/assets/effects/crt-overlay.css", "status": "new", "description": "Relocated from src/effects/" },
                    { "path": "apps/scene-engine/assets/glyphs/CODECAINE.css-layers.svg", "status": "new", "description": "Copied from font-creation outputs (~32KB SVG with 47 named data-layer groups)" },
                    { "path": "apps/scene-engine/public/media/", "status": "removed", "description": "Empty after move; remove the directory" },
                    { "path": "apps/scene-engine/src/effects/", "status": "removed", "description": "Empty after move; remove the directory" }
                  ],
                  "tree": null
                }
              },
              "actions": [
                { "id": 1, "command": "MOVE FILE apps/scene-engine/public/media/test-fire-2.mp4 TO apps/scene-engine/assets/media/test-fire-2.mp4 (use git mv to preserve history; create assets/media/ if missing)", "file": "apps/scene-engine/assets/media/test-fire-2.mp4", "status": "pending" },
                { "id": 2, "command": "MOVE FILE apps/scene-engine/src/effects/crt-overlay.css TO apps/scene-engine/assets/effects/crt-overlay.css (use git mv to preserve history; create assets/effects/ if missing)", "file": "apps/scene-engine/assets/effects/crt-overlay.css", "status": "pending" },
                { "id": 3, "command": "CREATE FILE apps/scene-engine/assets/glyphs/CODECAINE.css-layers.svg by copying apps/font-creation/generation/melee-3/outputs/generated/word/CODECAINE.css-layers.svg verbatim (cp; do not modify SVG content)", "file": "apps/scene-engine/assets/glyphs/CODECAINE.css-layers.svg", "status": "pending" },
                { "id": 4, "command": "REMOVE empty directory apps/scene-engine/public/media/ (rmdir; if .gitkeep exists from CP1, delete it first)", "file": "apps/scene-engine/public/media/", "status": "pending" },
                { "id": 5, "command": "REMOVE empty directory apps/scene-engine/src/effects/ (rmdir)", "file": "apps/scene-engine/src/effects/", "status": "pending" }
              ]
            },
            {
              "id": 2,
              "title": "Author assets/registry.json catalogue",
              "description": "Create apps/scene-engine/assets/registry.json — the master catalogue. Format: a flat JSON object keyed by asset id, each value an object with { type, path }. id is the stable handle scenes will use (kebab-case). type is one of media | effect | glyph-group | component | audio (only the first three are populated this checkpoint). path is the URL-style path Vite resolves at runtime, beginning with /assets/. Three entries on day one mirroring task 1's relocations: 'bg-video' → media, /assets/media/test-fire-2.mp4 ; 'crt-overlay' → effect, /assets/effects/crt-overlay.css ; 'codecaine-logo' → glyph-group, /assets/glyphs/CODECAINE.css-layers.svg. Keep the file pretty-printed (2-space indent) — both the editor (CP4) and the agent will diff this file frequently and stable formatting matters. Do NOT add a top-level wrapper like { entries: {...} }; keep it flat for one-line lookups by id.",
              "status": "pending",
              "context": {
                "read_before": [
                  { "file": ".spectre/sessions/2026-04-29_frontend-scene-system_aesqad/spec.md", "lines": "295-302", "purpose": "Confirms five asset types (media, effect, glyph-group, component, audio); only first three apply this checkpoint" },
                  { "file": "apps/scene-engine/assets/", "lines": "1-1", "purpose": "Confirm the assets/ tree exists from task 1 before placing registry.json at its root" }
                ],
                "related_files": [
                  "apps/scene-engine/assets/glyphs/CODECAINE.css-layers.svg",
                  "apps/scene-engine/assets/media/test-fire-2.mp4",
                  "apps/scene-engine/assets/effects/crt-overlay.css"
                ]
              },
              "depends_on": [1],
              "file_context": {
                "beginning": {
                  "files": [
                    { "path": "apps/scene-engine/assets/registry.json", "status": "new", "description": "Does not exist yet" }
                  ],
                  "tree": null
                },
                "ending": {
                  "files": [
                    { "path": "apps/scene-engine/assets/registry.json", "status": "new", "description": "Flat catalogue: { 'bg-video': {type, path}, 'crt-overlay': {...}, 'codecaine-logo': {...} }" }
                  ],
                  "tree": null
                }
              },
              "actions": [
                { "id": 1, "command": "CREATE FILE apps/scene-engine/assets/registry.json", "file": "apps/scene-engine/assets/registry.json", "status": "pending" },
                { "id": 2, "command": "ADD JSON object with three id-keyed entries: 'bg-video': {type:'media', path:'/assets/media/test-fire-2.mp4'}, 'crt-overlay': {type:'effect', path:'/assets/effects/crt-overlay.css'}, 'codecaine-logo': {type:'glyph-group', path:'/assets/glyphs/CODECAINE.css-layers.svg'} — flat (no entries wrapper); 2-space indent", "file": "apps/scene-engine/assets/registry.json", "status": "pending" }
              ]
            }
          ]
        },
        {
          "id": 2,
          "title": "Registry loader + resolve layer.asset through registry",
          "objective": "Wire the registry into the runtime: a loader module that fetches registry.json once at boot and exposes resolveAsset(id), then update scene-renderer + the existing media/css-effect renderers to look up layer.asset (now an id) through the registry instead of treating it as a literal path. Unknown ids must warn clearly and skip the layer rather than crash.",
          "status": "pending",
          "task_seeds": [
            { "title": "Create registry loader module", "intent": "apps/scene-engine/src/renderer/asset-registry.js — exports loadRegistry(url) that fetches and caches the catalogue, plus resolveAsset(id) that returns the entry { type, path } or null with a console.warn. Singleton cache keyed by url; second call returns cached registry.", "processed": true, "task_id": 3 },
            { "title": "Wire registry resolution into scene-renderer + media + css-effect", "intent": "Update renderScene() to await registry load before iterating layers. Update renderMedia and renderCssEffect to accept the resolved asset path (or full entry) instead of a raw path string — the simplest cut is for renderScene to resolve layer.asset → path before calling the per-type renderer, passing both the layer and the resolved path. Layers whose asset id is not in the registry are skipped with a warning.", "processed": true, "task_id": 4 }
          ],
          "tasks": [
            {
              "id": 3,
              "title": "Create registry loader module",
              "description": "Build the registry runtime. Create apps/scene-engine/src/renderer/asset-registry.js exporting two functions: (1) loadRegistry(url = '/assets/registry.json') — async; fetches the JSON, stores it in a module-scoped Map, returns the parsed object; if already loaded for this url, returns the cached value without re-fetching. (2) resolveAsset(id) — sync; returns the registry entry { type, path } for the id, or null and emits console.warn(`[asset-registry] Unknown asset id: ${id}`). The module also exports getRegistry() for any consumer that needs the raw catalogue (e.g. CP4's asset browser). No side-effect imports; the consumer (scene-renderer in task 4) is responsible for awaiting loadRegistry before calling resolveAsset. Behavior on missing registry.json: log error, leave cache empty so resolveAsset returns null for everything (the renderer will then warn-and-skip per layer rather than failing the whole scene).",
              "status": "pending",
              "context": {
                "read_before": [
                  { "file": "apps/scene-engine/assets/registry.json", "lines": "1-20", "purpose": "Confirm the shape resolveAsset will be returning — flat id-keyed object with {type, path} entries" },
                  { "file": "apps/scene-engine/src/renderer/scene-renderer.js", "lines": "1-30", "purpose": "Understand the current renderScene flow that task 4 will modify to call loadRegistry + resolveAsset" }
                ],
                "related_files": [
                  "apps/scene-engine/src/renderer/asset-renderers/index.js"
                ]
              },
              "depends_on": [2],
              "file_context": {
                "beginning": {
                  "files": [
                    { "path": "apps/scene-engine/src/renderer/asset-registry.js", "status": "new", "description": "Does not exist yet" }
                  ],
                  "tree": null
                },
                "ending": {
                  "files": [
                    { "path": "apps/scene-engine/src/renderer/asset-registry.js", "status": "new", "description": "Exports loadRegistry(url), resolveAsset(id), getRegistry(); module-scoped cache; warn-on-unknown" }
                  ],
                  "tree": null
                }
              },
              "actions": [
                { "id": 1, "command": "CREATE FILE apps/scene-engine/src/renderer/asset-registry.js", "file": "apps/scene-engine/src/renderer/asset-registry.js", "status": "pending" },
                { "id": 2, "command": "ADD VAR cache = new Map() at module scope (key: url, value: parsed registry object)", "file": "apps/scene-engine/src/renderer/asset-registry.js", "status": "pending" },
                { "id": 3, "command": "ADD VAR currentUrl = null at module scope (tracks which url's registry is the active one for resolveAsset)", "file": "apps/scene-engine/src/renderer/asset-registry.js", "status": "pending" },
                { "id": 4, "command": "ADD async FUNCTION loadRegistry(url = '/assets/registry.json'): if cache.has(url), set currentUrl=url and return cache.get(url); otherwise try { fetch(url) → .json() }, set cache.set(url, parsed), set currentUrl=url, return parsed; on fetch/parse failure console.error(`[asset-registry] failed to load ${url}`, err) and set cache.set(url, {}) so resolveAsset returns null cleanly", "file": "apps/scene-engine/src/renderer/asset-registry.js", "status": "pending" },
                { "id": 5, "command": "ADD FUNCTION resolveAsset(id): if !currentUrl, console.warn('[asset-registry] resolveAsset called before loadRegistry') and return null; entry = cache.get(currentUrl)?.[id]; if !entry, console.warn(`[asset-registry] Unknown asset id: ${id}`) and return null; return entry", "file": "apps/scene-engine/src/renderer/asset-registry.js", "status": "pending" },
                { "id": 6, "command": "ADD FUNCTION getRegistry(): return cache.get(currentUrl) || null", "file": "apps/scene-engine/src/renderer/asset-registry.js", "status": "pending" },
                { "id": 7, "command": "EXPORT loadRegistry, resolveAsset, getRegistry as named exports", "file": "apps/scene-engine/src/renderer/asset-registry.js", "status": "pending" }
              ]
            },
            {
              "id": 4,
              "title": "Wire registry resolution into scene-renderer + media + css-effect",
              "description": "Make every layer go through the registry. Update apps/scene-engine/src/renderer/scene-renderer.js so renderScene becomes async: at start, await loadRegistry(); for each layer, call resolveAsset(layer.asset) — if null, console.warn(`[scene-renderer] Skipping layer ${layer.id}: unknown asset ${layer.asset}`) and continue; otherwise call getRenderer(layer.type)(layer, entry) where entry is { type, path }. Update apps/scene-engine/src/renderer/asset-renderers/media.js: renderMedia signature changes to renderMedia(layer, entry); use entry.path for the <video src=>. Update apps/scene-engine/src/renderer/asset-renderers/css-effect.js: renderCssEffect signature changes to renderCssEffect(layer, entry); pass entry.path to ensureStylesheet. Also update apps/scene-engine/src/main.js so the boot() function awaits renderScene's promise (it already may, but verify). The caller-pattern reorg makes layer.asset always an id from CP2 forward. No fallback to treating layer.asset as a literal path — clean break, keeps the code honest.",
              "status": "pending",
              "context": {
                "read_before": [
                  { "file": "apps/scene-engine/src/renderer/scene-renderer.js", "lines": "1-40", "purpose": "Current renderScene loop that needs to become async + registry-aware" },
                  { "file": "apps/scene-engine/src/renderer/asset-renderers/media.js", "lines": "1-30", "purpose": "Current renderMedia signature using layer.asset directly" },
                  { "file": "apps/scene-engine/src/renderer/asset-renderers/css-effect.js", "lines": "1-40", "purpose": "Current renderCssEffect signature using layer.asset directly" },
                  { "file": "apps/scene-engine/src/main.js", "lines": "1-30", "purpose": "Confirm boot() awaits renderScene; if not, add await" },
                  { "file": "apps/scene-engine/src/renderer/asset-registry.js", "lines": "1-30", "purpose": "Confirm exported function names and signatures (loadRegistry, resolveAsset)" }
                ],
                "related_files": [
                  "apps/scene-engine/src/renderer/asset-renderers/index.js"
                ]
              },
              "depends_on": [3],
              "file_context": {
                "beginning": {
                  "files": [
                    { "path": "apps/scene-engine/src/renderer/scene-renderer.js", "status": "exists", "description": "Sync renderScene from CP1; treats layer.asset as raw path passed to renderers" },
                    { "path": "apps/scene-engine/src/renderer/asset-renderers/media.js", "status": "exists", "description": "renderMedia(layer) reads layer.asset directly" },
                    { "path": "apps/scene-engine/src/renderer/asset-renderers/css-effect.js", "status": "exists", "description": "renderCssEffect(layer) reads layer.asset directly" }
                  ],
                  "tree": null
                },
                "ending": {
                  "files": [
                    { "path": "apps/scene-engine/src/renderer/scene-renderer.js", "status": "modified", "description": "Async; awaits loadRegistry(); resolves each layer via resolveAsset(layer.asset); warn-and-skip on unknown id; passes entry to per-type renderers" },
                    { "path": "apps/scene-engine/src/renderer/asset-renderers/media.js", "status": "modified", "description": "renderMedia(layer, entry) — uses entry.path for <video src>" },
                    { "path": "apps/scene-engine/src/renderer/asset-renderers/css-effect.js", "status": "modified", "description": "renderCssEffect(layer, entry) — passes entry.path to ensureStylesheet" },
                    { "path": "apps/scene-engine/src/main.js", "status": "modified", "description": "boot() awaits renderScene (likely already does)" }
                  ],
                  "tree": null
                }
              },
              "actions": [
                { "id": 1, "command": "UPDATE apps/scene-engine/src/renderer/scene-renderer.js: ADD import { loadRegistry, resolveAsset } from './asset-registry.js' AT TOP", "file": "apps/scene-engine/src/renderer/scene-renderer.js", "status": "pending" },
                { "id": 2, "command": "REFACTOR FUNCTION renderScene to async: at start, await loadRegistry()", "file": "apps/scene-engine/src/renderer/scene-renderer.js", "status": "pending" },
                { "id": 3, "command": "UPDATE per-layer loop in renderScene: REPLACE direct getRenderer(layer.type)(layer) call WITH: const entry = resolveAsset(layer.asset); if (!entry) { console.warn(`[scene-renderer] Skipping layer ${layer.id}: unknown asset ${layer.asset}`); continue; } const el = await getRenderer(layer.type)(layer, entry); — note the await covers both sync and async renderers", "file": "apps/scene-engine/src/renderer/scene-renderer.js", "status": "pending" },
