{
  "$schema": "Plan schema for session checkpoint-based planning (v2)",

  "session_id": "2026-04-29_frontend-scene-system_aesqad",
  "spec_reference": "./spec.md",
  "created_at": "2026-04-29T17:05:00+00:00",
  "updated_at": "2026-04-29T17:30:00+00:00",
  "status": "draft",

  "checkpoints": [
    {
      "id": 1,
      "title": "Renderer Foundation + Title Skeleton (tracer bullet)",
      "goal": "Stand up a new apps/scene-engine/ Vite app that loads a hardcoded scenes/title/scene.json (one media bg layer + one effect overlay layer) and renders it onto a 1440x1080 stage in the browser. End-to-end pipe with two layer types only — no registry, no editor, no glyph-group yet.",
      "prerequisites": [],
      "status": "pending",
      "testing_strategy": "Manual: run dev server, open browser at /, see test-fire-2.mp4 looping fullscreen with CRT scanlines/vignette overlay on top. Confirm stage dimensions render at 1440x1080 (with appropriate scaling/letterboxing). scene.json edits to opacity/blend on either layer reflect after reload. Visual smoke test only — no automated tests this checkpoint.",
      "task_groups": [
        {
          "id": 1,
          "title": "Scaffold scene-engine + migrate minimal assets",
          "objective": "Create the new apps/scene-engine/ Vite project shell and copy in the two assets the tracer-bullet title scene needs (bg video + CRT effect CSS). No renderer yet — just the empty app and its asset deps.",
          "status": "pending",
          "task_seeds": [
            { "title": "Scaffold scene-engine Vite project shell", "intent": "Stand up apps/scene-engine/ as a sibling to apps/frontend/ with package.json, vite.config.js, index.html (stage container), base stage CSS, and an empty main.js entry. Pattern after apps/frontend/ but with a single entry (multi-page comes in CP6).", "processed": true, "task_id": 1 },
            { "title": "Migrate bg video + CRT effect CSS into scene-engine", "intent": "Copy test-fire-2.mp4 from apps/font-creation/generation/melee-3/inputs/extras/ into apps/scene-engine/public/media/. Extract the .crt rules from apps/frontend/src/styles/effects.css (lines 38-61) into a standalone apps/scene-engine/src/effects/crt-overlay.css that the css-effect renderer can attach.", "processed": true, "task_id": 2 }
          ],
          "tasks": [
            {
              "id": 1,
              "title": "Scaffold scene-engine Vite project shell",
              "description": "Create the apps/scene-engine/ directory and populate it with the minimal Vite project files: package.json (vite ^8 dev dep, dev/build/preview scripts), vite.config.js (single-page root config — multi-page rollup inputs deferred to CP6), index.html with a #stage-wrap > #stage container and a module script tag pointing at /src/main.js, src/styles/stage.css that sizes #stage to exactly 1440x1080 and centers it inside #stage-wrap with appropriate scaling for smaller viewports, and src/main.js as an empty entry stub that imports the stage CSS. No renderer logic in this task — that's task 1.2.1. After this task the dev server should boot and show a black 1440x1080 stage with no errors.",
              "status": "pending",
              "context": {
                "read_before": [
