        { "id": 2, "command": "REFACTOR FUNCTION renderGlyphGroup body: EXTRACT the viewBox-parsing block into `const vb = parseViewBox(svg)` returning { w, h }; ADD FUNCTION parseViewBox(svg) at module scope: const vbAttr = svg.getAttribute('viewBox'); if (vbAttr) { const [,,w,h] = vbAttr.split(/\\s+/).map(Number); return { w, h }; } return { w: parseFloat(svg.getAttribute('width') || '0'), h: parseFloat(svg.getAttribute('height') || '0') }; — keeps the wrapper sizing and foreignObject sizing in lockstep", "file": "apps/scene-engine/src/renderer/asset-renderers/glyph-group.js", "status": "pending" },
        { "id": 3, "command": "ADD async FUNCTION mountForeignChild(svg, child, vb, anchor) at module scope: const entry = resolveAsset(child.asset); if (!entry) { console.warn(`[glyph-group] Foreign child '${child.id}' has unknown asset '${child.asset}'`); return null; } const { getRenderer } = await import('./index.js'); const rendererFn = getRenderer(child.type); const el = await rendererFn(child, entry); const fo = document.createElementNS('http://www.w3.org/2000/svg', 'foreignObject'); fo.setAttribute('x', '0'); fo.setAttribute('y', '0'); fo.setAttribute('width', String(vb.w)); fo.setAttribute('height', String(vb.h)); const props = child.properties || {}; if (typeof props.opacity === 'number') fo.style.opacity = String(props.opacity); if (typeof props.blend === 'string') fo.style.mixBlendMode = props.blend; const xhtmlWrap = document.createElementNS('http://www.w3.org/1999/xhtml', 'div'); xhtmlWrap.setAttribute('style', 'width:100%;height:100%;position:relative'); xhtmlWrap.appendChild(el); fo.appendChild(xhtmlWrap); if (anchor) svg.insertBefore(fo, anchor.nextSibling); else svg.insertBefore(fo, svg.firstChild); return fo;", "file": "apps/scene-engine/src/renderer/asset-renderers/glyph-group.js", "status": "pending" },
        { "id": 4, "command": "UPDATE renderGlyphGroup children-loop (added in CP3 task 1 action 2): REPLACE the named-only loop body WITH a dual-branch loop that maintains lastNamedAnchor: let lastNamedAnchor = null; for (const child of (layer.children ?? [])) { if (child.layer) { const matched = svg.querySelector(`[data-layer=\"${child.layer}\"]`); applySubLayerOverride(svg, child); if (matched) lastNamedAnchor = matched; } else if (child.type) { const fo = await mountForeignChild(svg, child, vb, lastNamedAnchor); if (fo) lastNamedAnchor = fo; } }", "file": "apps/scene-engine/src/renderer/asset-renderers/glyph-group.js", "status": "pending" },
        { "id": 5, "command": "REFACTOR FUNCTION applySubLayerOverride to take the matched element as a parameter (so the loop's querySelector result is reused instead of looking up twice): CHANGE signature to applySubLayerOverride(el, child) and DELETE the internal querySelector + null check (the caller now handles `if (!matched) console.warn` before invoking — UPDATE caller in the loop accordingly: `if (!matched) { console.warn(`[glyph-group] Unknown sub-layer: ${child.layer}`); continue; } applySubLayerOverride(matched, child); lastNamedAnchor = matched;`)", "file": "apps/scene-engine/src/renderer/asset-renderers/glyph-group.js", "status": "pending" },
        { "id": 6, "command": "VERIFY apps/scene-engine/src/renderer/asset-renderers/index.js still imports glyph-group eagerly (for registerRenderer call) — the dynamic import inside mountForeignChild does NOT create a top-level cycle because it executes only when a foreign child is processed at runtime; index.js itself does not need to change in this task", "file": "apps/scene-engine/src/renderer/asset-renderers/index.js", "status": "pending" }
